// AI: below section was generated by an AI
// Compile-time test of the bit-packed pixel layout (no code or data ends up in the firmware).
// Checks PixelBus::packChannels()/unpackChannels() with the Govee G1151 row of LED_TYPE_TABLE against bytes worked out
// independently: 90 bits per chip, 5 x (2 control bits + 16-bit value) for G, R, B, CW, WW (research FINDINGS.md).
// A wrong gap entry or packing change stops the build.

#include "WLEDpixelBus.h"
#include "../../led_types.h"

namespace {

struct Pack : WLEDpixelBus::PixelBus { // only to reach the protected static helpers, never instantiated
  using WLEDpixelBus::PixelBus::packChannels;
  using WLEDpixelBus::PixelBus::unpackChannels;
};

constexpr uint8_t NCH = 5, BITS = 90, BYTES = (2 * BITS + 7) / 8;
constexpr const uint8_t* GAPS = ledType(TYPE_G1151)->gaps;

struct Buf { uint8_t b[BYTES + 1] = {}; }; // + 1: writeBits() may read one byte past the source

// two pixels (wire order G, R, B, CW, WW, 16-bit big endian), the second one not byte aligned (starts at bit 90)
constexpr uint16_t PX[2][NCH] = {{0x1234, 0x5678, 0x9ABC, 0xDEF0, 0x0F1E}, {0xFFFF, 0x8001, 0x0001, 0x8000, 0xAAAA}};
constexpr uint8_t EXPECTED[BYTES] = {0x04, 0x8D, 0x05, 0x67, 0x82, 0x6A, 0xF0, 0xDE, 0xF0, 0x03, 0xC7, 0x8F,
                                     0xFF, 0xF2, 0x00, 0x04, 0x00, 0x01, 0x20, 0x00, 0x0A, 0xAA, 0xA0};

constexpr Buf channels(const uint16_t (&v)[NCH]) {
  Buf s;
  for (uint8_t c = 0; c < NCH; c++) { s.b[2 * c] = v[c] >> 8; s.b[2 * c + 1] = v[c] & 0xFF; }
  return s;
}

constexpr Buf packTwo() {
  Buf out;
  for (uint8_t p = 0; p < 2; p++) {
    const Buf s = channels(PX[p]);
    Pack::packChannels(out.b, p * BITS, s.b, 2, NCH, GAPS);
  }
  return out;
}

constexpr bool packsAsExpected() {
  const Buf out = packTwo();
  for (uint8_t i = 0; i < BYTES; i++) if (out.b[i] != EXPECTED[i]) return false;
  return true;
}

constexpr bool unpacksBack(uint8_t p) {
  const Buf packed = packTwo();
  Buf s;
  Pack::unpackChannels(s.b, packed.b, p * BITS, 2, NCH, GAPS);
  const Buf want = channels(PX[p]);
  for (uint8_t i = 0; i < 2 * NCH; i++) if (s.b[i] != want.b[i]) return false;
  return true;
}

// absolute bit of channel ch's most significant bit in a chip word
constexpr int msbBit(uint8_t ch) {
  uint16_t v[NCH] = {};
  v[ch] = 0x8000;
  Buf s;
  for (uint8_t c = 0; c < NCH; c++) { s.b[2 * c] = v[c] >> 8; s.b[2 * c + 1] = v[c] & 0xFF; }
  Buf out;
  Pack::packChannels(out.b, 0, s.b, 2, NCH, GAPS);
  for (int bit = 0; bit < BITS; bit++) if (out.b[bit >> 3] & (0x80 >> (bit & 7))) return bit;
  return -1;
}

constexpr unsigned gapTotal() { unsigned t = 0; for (uint8_t c = 0; c < NCH; c++) t += GAPS[c]; return t; }

static_assert(NCH * 16 + gapTotal() == BITS, "G1151: a chip word is 90 bits");
static_assert(msbBit(0) == 2 && msbBit(1) == 20 && msbBit(2) == 38 && msbBit(3) == 56 && msbBit(4) == 74,
              "G1151: green, red, blue, cool and warm white each start after 2 control bits");
static_assert(packsAsExpected(), "bit packing: two G1151 pixels do not give the expected bytes");
static_assert(unpacksBack(0) && unpacksBack(1), "bit packing: unpacking does not give the packed pixels back");

} // namespace
// AI: end
